package android.os;import java.util.*;public class Handler{public static List<Runnable> pending=new ArrayList<>();public Handler(Looper l){}public void postDelayed(Runnable task,long ms){pending.add(task);}public void removeCallbacks(Runnable task){pending.removeIf(x->x==task);}public static void fire(){var tasks=new ArrayList<>(pending);pending.clear();for(Runnable task:tasks)task.run();}}
